(()=>{'use strict';const keys=['utm_source','utm_medium','utm_campaign','utm_content','utm_term','utm_id','sck','src','xcod','fbclid'];const key='lina-mx-attribution-v1';let saved={};try{saved=JSON.parse(sessionStorage.getItem(key)||'{}')||{}}catch{}const search=new URLSearchParams(location.search);if(keys.some(k=>search.has(k)))saved={};for(const k of keys){const v=search.get(k);if(v)saved[k]=v.slice(0,1500)}try{sessionStorage.setItem(key,JSON.stringify(saved))}catch{}window.hotmartDestination=(value)=>{const url=new URL(value);if(url.protocol!=='https:'||url.hostname!=='pay.hotmart.com')throw Error('Invalid checkout');for(const k of keys)if(saved[k])url.searchParams.set(k,saved[k]);return url.href;};})();